// The remote copy of the MCP server (CONTRIBUTING.md → Remote server): worker/index.ts, with the index
// (data/*.json, generated by `pnpm generate`) bundled in, and the block and template files (data/sources/)
// as static assets the Worker reads on demand. No secrets or storage. Written by hand, like apps/docs's,
// not by `cf init`. Deploy: `pnpm cf:deploy`.
import { bindings, defineConfig } from 'cf/config'

export default defineConfig({
  worker: {
    name: 'youj-mcp',
    compatibilityDate: '2026-09-25',
    entrypoint: './worker/index.ts',
    env: { ASSETS: bindings.assets() },
    // Every request goes through the Worker (so the STEALTH_TOKEN gate covers the files too); only it reads the assets.
    assets: { runWorkerFirst: true },
    observability: { enabled: true },
    // Attached on deploy (the zone youj.dev must be on the account).
    domains: ['mcp.youj.dev'],
  },
})
